def art(id_, titre, resume, fait, chiffres, mecanisme, mot, change, retenir, limites, question, verif, actions, entites=None, notions=None):
    return {
        "statut": "publié", "une": False, "corrections": [], "auteur": "Rédaction EFA", "origine": "dossier « Les leçons de la BRVM », calculs Ma BRVM du " + J,
        "publication": J, "maj": J, "id": J + "-" + id_, "categorie": "brvm", "rubrique": "Les leçons de la BRVM",
        "titre": titre, "resume": resume, "pays": ["UEMOA"], "entites": ["BRVM"] + (entites or []), "notions": notions or [],
        "evenement": "2026-11-20", "evenement_label": "Calcul arrêté à la séance du 20 novembre 2026",
        "fait": fait, "chiffres": [{"valeur": v, "libelle": l, "periode": p, "calcul_efa": True} for v, l, p in chiffres],
        "mecanisme": mecanisme, "mot": {"terme": mot[0], "definition": mot[1]}, "change": change, "retenir": retenir,
        "limites": limites + [GARDE], "question": question,
        "verif": {"q": verif[0], "choix": verif[1], "bonne": verif[2], "explication": verif[3]},
        "actions": [{"type": "Outil", "titre": t, "description": d, "url": u} for t, d, u in actions], "sources": SRC,
    }


