def main():
    p = os.path.join(RACINE, 'news', 'news-data.json')
    d = json.load(open(p, encoding='utf-8'))
    ids = {a['id'] for a in d['articles']}
    neufs = [a for a in A if a['id'] not in ids]
    d['articles'] = neufs + d['articles']
    json.dump(d, open(p, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print('%d article(s) ajouté(s), %d déjà présents' % (len(neufs), len(A) - len(neufs)))


if __name__ == '__main__':
    main()
